text:
{
  "jobs": [
    {
      "text": "Регулярно созванивается с матерью 67 лет; по вторникам она водит его сына в музыкалку, и на обратном пути они звонят ему и дают послушать, что ребёнок разучил",
      "quote": "Мне 45, я вожу трамвай. Чаще всего созваниваюсь с мамой, ей 67. По вторникам она водит моего сына в музыкалку, и у них уже традиция звонить мне на обратном пути и давать послушать, что он сегодня разучил."
    },
    {
      "text": "Заботится о матери в ситуациях, когда она ждёт доставку и спускается с четвёртого этажа",
      "quote": "Мама, например, заказывает продукты и подолгу спускается с четвёртого этажа. Когда звонит доставка, она уже одной рукой куртку застёгивает. Я за неё переживаю именно в такие минуты."
    },
    {
      "text": "Обсуждает с матерью случаи мошенничества и делится предупреждениями",
      "quote": "Вот это мы с ней хорошо обсудили."
    },
    {
      "text": "Раньше пересылал матери предупреждения из домового чата",
      "quote": "А раньше я просто пересылал ей предупреждения из нашего домового чата."
    },
    {
      "text": "Готов платить за защиту для себя и матери, если увидит, что она срабатывает",
      "quote": "За нас с мамой рублей сто в месяц я бы добавил к тарифу, если бы за время пробы увидел, что защита срабатывает и в мессенджере."
    }
  ],
  "pains": [
    {
      "text": "Сам попался на мошеннический звонок «курьера» в мессенджере и заплатил 390 рублей, потому что заканчивался перерыв",
      "quote": "Заказал сыну кроссовки и как раз ждал доставку, когда мне в мессенджере позвонил «курьер». Сказал, что нужно доплатить 390 рублей. У меня заканчивался перерыв, я заплатил и побежал на рейс."
    },
    {
      "text": "Не удалось вернуть деньги; доставка изначально была бесплатной",
      "quote": "Доставка с самого начала была бесплатная, деньги вернуть не удалось."
    },
    {
      "text": "Было неловко рассказывать матери, так как сам её ранее убеждал, что таким звонкам никто не верит",
      "quote": "Маме рассказывать было неловко. Я ведь до этого сам ей говорил: «Ну кто сейчас верит таким звонкам?»"
    },
    {
      "text": "Мать спросила, почему именно он поверил",
      "quote": "А когда всё-таки рассказал, она спросила, почему именно я поверил."
    },
    {
      "text": "Неудобно и тяжело в момент, когда звонка действительно ждёшь — легко согласиться на что угодно",
      "quote": "Неудобно в тот момент, когда звонка действительно ждёшь."
    },
    {
      "text": "По себе знает, как легко согласиться на что угодно, когда в голове одно — человек внизу ждёт",
      "quote": "По себе знаю, как легко согласиться на что угодно, когда в голове одно — человек внизу ждёт."
    },
    {
      "text": "За рулём не может перезвонить",
      "quote": "За рулём я всё равно не смогу перезвонить."
    },
    {
      "text": "Сообщение «вашей маме звонили мошенники» вызвало бы тревогу на весь следующий рейс",
      "quote": "А от сообщения «вашей маме звонили мошенники» я бы весь следующий рейс думал, успела она с ними поговорить или нет."
    },
    {
      "text": "Пробный месяц платного определителя не показал пользы, отключил",
      "quote": "Пробовал платный определитель, но за пробный месяц так и не заметил от него пользы и отключил."
    }
  ],
  "current_solutions": [
    {
      "text": "При звонке, касающемся заказа, открывают сам заказ и смотрят, что там написано",
      "quote": "Теперь, если звонок касается заказа, открываем сам заказ и смотрим, что там написано."
    },
    {
      "text": "Идею проверять заказ предложила мать",
      "quote": "Это, кстати, мама предложила."
    },
    {
      "text": "Раньше пересылал матери предупреждения из домового чата",
      "quote": "А раньше я просто пересылал ей предупреждения из нашего домового чата."
    },
    {
      "text": "Пробовал платный определитель, но отключил из-за отсутствия пользы",
      "quote": "Пробовал платный определитель, но за пробный месяц так и не заметил от него пользы и отключил."
    }
  ],
  "barriers": [
    {
      "text": "Барьер оплаты: сейчас отдельно за такую защиту не платит",
      "quote": "Сейчас отдельно за такую защиту не плачу."
    },
    {
      "text": "Барьер выбора/понимания: готов платить только если за время пробы увидит, что защита срабатывает и в мессенджере; это важнее самой цены",
      "quote": "За нас с мамой рублей сто в месяц я бы добавил к тарифу, если бы за время пробы увидел, что защита срабатывает и в мессенджере. Для меня это важнее самой цены."
    },
    {
      "text": "Барьер понимания: остановило бы, если по уведомлению непонятно, нужно ли что-то делать прямо сейчас",
      "quote": "Меня бы остановило, если по уведомлению непонятно, нужно ли что-то делать прямо сейчас."
    }
  ],
  "triggers": [
    {
      "text": "Собственный случай: мошеннический звонок «курьера» в мессенджере с требованием доплатить 390 рублей",
      "quote": "Последний раз попался я сам. Заказал сыну кроссовки и как раз ждал доставку, когда мне в мессенджере позвонил «курьер». Сказал, что нужно доплатить 390 рублей."
    },
    {
      "text": "На следующий день приехал настоящий курьер и не понял, о чём речь",
      "quote": "На следующий день приехал настоящий курьер. Я ещё пожаловался ему, что странно они деньги собирают. Он вообще не понял, о чём я."
    },
    {
      "text": "Обращался в магазин и в банк, но деньги вернуть не удалось",
      "quote": "Написал в магазин, потом в банк. Доставка с самого начала была бесплатная, деньги вернуть не удалось."
    },
    {
      "text": "Разговор с матерью о том, почему он поверил, подтолкнул к обсуждению",
      "quote": "А когда всё-таки рассказал, она спросила, почему именно я поверил. Вот это мы с ней хорошо обсудили."
    },
    {
      "text": "Мать прислала скриншот, что он отправил ей одну и ту же историю уже три раза",
      "quote": "Как-то она мне в ответ прислала скриншот — оказалось, я ей одну и ту же историю отправил уже три раза."
    }
  ],
  "words": [
    "«курьер»",
    "доплатить 390 рублей",
    "перерыв",
